<tr><td style="padding-top:24px"><img src="https://wizzas-defectrag.hf.space/assets/email/robot-hello.gif" width="96" height="96" alt="DefectRAG robot waving hello" style="display:block;border:0;outline:none;border-radius:20px;width:96px;height:96px"></td></tr>
<tr><td style="padding-top:16px;color:{{ ({created:'#5b4fd6',updated:'#5b4fd6',reminder:'#b54708',overdue:'#9a4a0e',done:'#1b7f4b',cancelled:'#6b7280'})[($json.kind==='updated'&&['Resolved','Closed'].includes($json.state)?'done':$json.kind==='updated'&&$json.state==='Cancelled'?'cancelled':$json.kind)] }};font-size:13px;font-weight:600">{{ ({created:'New case',updated:'Quick update',reminder:'Friendly reminder',overdue:'Needs a little attention',done:'All done',cancelled:'Cancelled'})[($json.kind==='updated'&&['Resolved','Closed'].includes($json.state)?'done':$json.kind==='updated'&&$json.state==='Cancelled'?'cancelled':$json.kind)] }}</td></tr>
