<tr><td class="mu" style="padding:3px 16px 3px 0;color:#6b7280;font-size:14px;white-space:nowrap;vertical-align:top">Case</td><td class="tx" style="padding:3px 0;color:#111827;font-size:14px">{{ $json.case_id.slice(0,8) }}</td></tr>
<tr><td class="mu" style="padding:3px 16px 3px 0;color:#6b7280;font-size:14px;white-space:nowrap;vertical-align:top">Status</td><td class="tx" style="padding:3px 0;color:#111827;font-size:14px">{{ $json.state }}</td></tr>
<tr><td class="mu" style="padding:3px 16px 3px 0;color:#6b7280;font-size:14px;white-space:nowrap;vertical-align:top">Priority</td><td class="tx" style="padding:3px 0;color:#111827;font-size:14px"><span style="color:{{ ({Critical:'#c0362c',High:'#b54708'})[$json.priority] || '#111827' }};font-weight:{{ ['Critical','High'].includes($json.priority) ? '600' : '400' }}">{{ $json.priority }}</span></td></tr>
